# FDN Crossway Troublemakers: "Attacking Vampires you control have deathtouch and lifelink.
# Whenever a Vampire you control dies, you may pay 2 life. If you do, draw a card."
# [0]: one static of two grants (FDN Unflinching Courage's Seq of GRANT_ABILITY in a static, sorted
# by name: D23) over M21 Warded Battlements' "attacking creatures you control" narrowed to Vampires
# (Pack Leader's tribal SUBTYPE_EQ + TYPE_EQ Creature).
# [1]: a CreatureDiesEvent over Vampires you control (Troublemakers is one, so its own death counts,
# CR 603.10a); effect: M21 Ghostly Pilferer's verified "you may pay {2}. If you do, draw a card."
# with the cost a life payment (CostLife 2, Tavern Swindler's "Pay 3 life" part).
attacking_vampires = Selector(
    count=QUnbounded(),
    mode=SelectorMode.ALL,
    filter=FAnd(
        children=(
            FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
            FAtom(pred=FAtomPred.IS_ATTACKING),
            FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Vampire'),
            FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
        ),
    ),
    zones=(Zone(kind=ZoneKind.BATTLEFIELD, controller=ControllerRef.ANY),),
)
grants = StaticAbility(
    effect=Seq(
        steps=(
            A(Verb.GRANT_ABILITY, {
                'ability': KeywordAbility(keyword=Keyword.DEATHTOUCH),
                'target': attacking_vampires,
            }),
            A(Verb.GRANT_ABILITY, {
                'ability': KeywordAbility(keyword=Keyword.LIFELINK),
                'target': attacking_vampires,
            }),
        ),
    ),
)
vampire_dies = TriggeredAbility(
    event=CreatureDiesEvent(
        filter=FAnd(
            children=(
                FAtom(pred=FAtomPred.CONTROLLER_IS, who=ControllerRef.YOU),
                FAtom(pred=FAtomPred.SUBTYPE_EQ, string_value='Vampire'),
                FAtom(pred=FAtomPred.TYPE_EQ, string_value='Creature'),
            ),
        ),
    ),
    condition=None,
    effect=Seq(
        steps=(
            OptionalEffect(
                inner=A(Verb.PAY, {'cost': Cost(parts=(CostLife(amount=QConst(value=2)),))}),
            ),
            Conditional(
                pred=FAtom(pred=FAtomPred.MAY_DONE),
                then_effect=A(Verb.DRAW, {'amount': QConst(value=1), 'controller': ControllerRef.YOU}),
            ),
        ),
    ),
)
abilities = [grants, vampire_dies, *compiled]
